1	// Acceptance test for the change request:
2	//   "Make sure that discount shows up everywhere I check what is owed. That means the invoice, the
3	//    statement and the home screen."
4	//
5	// An invoice can already carry a percentage DISCOUNT, and its detail page shows the subtotal, the
6	// discount and the final total (see invoice-discount.spec). What this change adds is that the
7	// discount must now flow through into "WHAT IS OWED" — the money still to be paid — in the three
8	// places the app answers that question:
9	//
10	//   1. THE INVOICE — how much is still left to pay on an invoice (invoice-due-amount, shown on each
11	//      invoice's row in its project's invoice list). Before this change it was the invoice's GROSS
12	//      amount minus payments; after it, it is the DISCOUNTED total (amount minus the discount) minus
13	//      payments.
14	//   2. THE STATEMENT — each invoice row's due (statement-invoice-due) and the client's outstanding
15	//      total (client-outstanding-total) on the client statement. These net off the discount as well
16	//      as payments.
17	//   3. THE HOME SCREEN — the dashboard's money owed (dashboard-outstanding-total), which sums the
18	//      DISCOUNTED totals of the sent invoices, not their gross amounts.
19	//
20	// WHY THESE VALUES. The discount in money is subtotal × percentage, and the discounted total is the
21	// subtotal (the invoice's amount) minus that. "What is owed" is then that discounted total minus any
22	// payments. The figures below are chosen so that only a figure that has genuinely had the discount
23	// taken off can be right — a value that still showed the gross amount (the pre-change behaviour), or
24	// that took the discount off only some of the invoices, is wrong in at least one assertion:
25	//   - a $500 invoice at 10% is a $450 total; with $100 paid, $350 is still owed (not $400, which is
26	//     the gross $500 less the $100 paid; not $450, which forgets the payment; not $500, the gross);
27	//   - an $800 invoice at 25% is a $600 total; unpaid, $600 is owed (not the gross $800);
28	//   - a $400 invoice at 25% is a $300 total; unpaid, $300 is owed.
29	//
30	// Money is shown "properly" everywhere in this app — a dollar sign and two decimal places, e.g.
31	// $350.00 (see money-format.spec) — so the invoice and statement figures are asserted as that money
32	// value, matched as CONTAINMENT so a surrounding label does not break the assertion while the
33	// leading "$" keeps a figure from matching inside a larger number. The dashboard figure may be shown
34	// bare or dressed up, so it is asserted as a standalone number token (as dashboard.spec does). Every
35	// figure stays under a thousand, so thousands grouping never arises.
36	//
37	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
38	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and an
39	// invoice honours { id, amount, projectId, status, discountPct }, `payments` honours
40	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
41	// assert on the audit channel.
42	import { test, expect, type Page, type Locator } from '@playwright/test';
43	import { resetAndSeed } from '../support/seed';
44	
45	// A money value shown properly: a dollar sign, the whole-dollar amount, a decimal point and exactly
46	// two cents digits (e.g. $350.00). Matched as CONTAINMENT so a label does not break the assertion,
47	// while the "$" keeps the figure from matching inside a larger number ("$3,500.00"). All amounts
48	// below stay under a thousand, so grouping never arises.
49	const money = (dollars: number): RegExp => new RegExp(`\\$${dollars}\\.00`);
50	
51	// A dashboard figure may be rendered bare (480) or dressed up ("$480.00"). Assert it CARRIES the
52	// number as a standalone token; the surrounding (^|\D)…(\D|$) keeps a smaller number from matching
53	// inside a larger one.
54	const asToken = (n: number): RegExp => new RegExp(`(^|\\D)${n}(\\D|$)`);
55	
56	// --- The invoice: how much is still left to pay, shown on the invoice's row in its project list. ---
57	
58	const invoiceDue = (page: Page, invoiceId: number): Locator =>
59	  page.getByTestId(`invoice-row-${invoiceId}`).getByTestId('invoice-due-amount');
60	
61	test.describe('The discount is taken off what is still owed on an invoice', () => {
62	  test('the amount still to pay is the discounted total minus payments, not the gross amount', async ({
63	    page,
64	  }) => {
65	    // Two sent invoices on one project, each with a discount:
66	    //   invoice 1: $500 at 10% -> $450 total; $100 paid -> $350 still to pay.
67	    //   invoice 2: $800 at 25% -> $600 total; nothing paid -> $600 still to pay.
68	    await resetAndSeed({
69	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
70	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
71	      invoices: [
72	        { id: 1, amount: 500, projectId: 1, status: 'SENT', discountPct: 10 },
73	        { id: 2, amount: 800, projectId: 1, status: 'SENT', discountPct: 25 },
74	      ],
75	      payments: [{ id: 1, invoiceId: 1, amount: 100, date: '2021-03-14' }],
76	    });
77	
78	    await page.goto('/projects/1');
79	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
80	
81	    // Invoice 1: owed is the discounted total less the payment, 450 - 100 = 350.
82	    await expect(invoiceDue(page, 1)).toContainText(money(350));
83	    // NOT the gross-less-payment (500 - 100 = 400, the pre-change reading): the discount is now off.
84	    await expect(invoiceDue(page, 1)).not.toContainText(money(400));
85	    // NOT the discounted total with the payment forgotten (450), nor the gross amount (500).
86	    await expect(invoiceDue(page, 1)).not.toContainText(money(450));
87	    await expect(invoiceDue(page, 1)).not.toContainText(money(500));
88	
89	    // Invoice 2: unpaid, so owed is its whole discounted total, 600 — not the gross 800.
90	    await expect(invoiceDue(page, 2)).toContainText(money(600));
91	    await expect(invoiceDue(page, 2)).not.toContainText(money(800));
92	  });
93	});
94	
95	// --- The statement: each invoice's due and the client's outstanding total. ---
96	
97	const statementDue = (page: Page, invoiceId: number): Locator =>
98	  page.getByTestId(`statement-invoice-row-${invoiceId}`).getByTestId('statement-invoice-due');
99	
100	async function openStatement(page: Page, clientId: number): Promise<void> {
101	  await page.goto(`/clients/${clientId}`);
102	  await expect(page.getByTestId('client-detail-page')).toBeVisible();
103	  const opener = page.getByTestId('client-statement-open');
104	  await expect(opener).toBeVisible();
105	  await opener.click();
106	  await expect(page.getByTestId('client-statement')).toBeVisible();
107	  await expect(page.getByTestId('client-statement-table')).toBeVisible();
108	}
109	
110	test.describe('The discount is taken off what a client owes on their statement', () => {
111	  test('each invoice row and the outstanding total net off the discount', async ({ page }) => {
112	    // Acme with two sent invoices across two projects, each discounted:
113	    //   invoice 1: $500 at 10% -> $450 total; $100 paid -> $350 due.
114	    //   invoice 2: $400 at 25% -> $300 total; nothing paid -> $300 due.
115	    // Outstanding = 350 + 300 = 650.
116	    await resetAndSeed({
117	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
118	      projects: [
119	        { id: 1, name: 'Website Redesign', clientId: 1 },
120	        { id: 2, name: 'Mobile App', clientId: 1 },
121	      ],
122	      invoices: [
123	        { id: 1, amount: 500, projectId: 1, status: 'SENT', discountPct: 10 },
124	        { id: 2, amount: 400, projectId: 2, status: 'SENT', discountPct: 25 },
125	      ],
126	      payments: [{ id: 1, invoiceId: 1, amount: 100, date: '2021-03-14' }],
127	    });
128	
129	    await openStatement(page, 1);
