import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useAllInvoices } from './allInvoices';
import { INVOICE_PAGE_SIZE, useInvoicePage } from './pagination';

// One place listing every invoice from every project. Reads its own query key and shows, per row,
// which project the invoice is for and what stage (status) it is at. When the shared `invoiceStatus`
// URL key (set by a toolbar control) names a stage, the list keeps only the rows at that stage.
export function AllInvoiceList() {
  const { data: invoices } = useAllInvoices();
  const [status] = useSearchParam('invoiceStatus', asString);
  const [page] = useInvoicePage();

  if (!invoices) {
    return null;
  }

  if (invoices.length === 0) {
    return <p data-testid="all-invoices-empty">No invoices yet.</p>;
  }

  const shown = status ? invoices.filter((invoice) => invoice.status === status) : invoices;
  // One page at a time: the pager owns the `invoicePage` key, we show only that window of rows.
  const start = (page - 1) * INVOICE_PAGE_SIZE;
  const pageRows = shown.slice(start, start + INVOICE_PAGE_SIZE);

  return (
    <>
    <AllInvoicesToolbar.Slot />
    <table data-testid="all-invoices-table">
      <thead>
        <tr>
          <th>Project</th>
          <th>Amount</th>
          <th>Stage</th>
        </tr>
      </thead>
      <tbody>
        {pageRows.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-project">{invoice.projectName}</td>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-status">{invoice.status}</td>
          </tr>
        ))}
      </tbody>
    </table>
    </>
  );
}

import { formatMoney } from '../../ui/money';
import { InvoiceLineItemRow } from '../../slots/defs/invoiceLineItemRow';
import { useLineItems } from './lineItems';
import { useInvoiceSummary } from './invoiceSummary';

// An invoice's line items and what they add up to. Reads its own query key (scoped to the invoice)
// and derives the invoice amount from the rows — the total is never stored on the client, so it
// always matches the list. Each row shows a description, how many, the price of each, and that
// line's own amount (qty * unit price). The table is always rendered, so an invoice with no lines
// yet still shows the region (and a $0.00 total) ready for the first line to be added.
export function LineItemList({ invoiceId }: { invoiceId: number }) {
  const { data: lineItems } = useLineItems(invoiceId);
  const { data: summary } = useInvoiceSummary(invoiceId);

  if (!lineItems) {
    return null;
  }

  // The lines sum to the subtotal; the invoice's amount is that less any discount, worked out on the
  // server (see the summary panel). Fall back to the subtotal while the summary loads — an invoice
  // with no discount bills its full subtotal.
  const subtotal = lineItems.reduce(
    (sum, line) => sum + Number(line.qty) * Number(line.unitPrice),
    0,
  );
  const total = summary ? Number(summary.total) : subtotal;

  return (
    <table data-testid="invoice-lineitems-table">
      <thead>
        <tr>
          <th>Description</th>
          <th>Qty</th>
          <th>Unit</th>
          <th>Unit price</th>
          <th>Amount</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {lineItems.map((line) => (
          <tr key={line.id} data-testid={`lineitem-row-${line.id}`}>
            <td data-testid="lineitem-description">{line.description}</td>
            <td data-testid="lineitem-qty">{line.qty}</td>
            <td data-testid="lineitem-unit">{line.unit}</td>
            <td data-testid="lineitem-unitprice">{formatMoney(line.unitPrice)}</td>
            <td data-testid="lineitem-amount">
              {formatMoney(Number(line.qty) * Number(line.unitPrice))}
            </td>
            <td>
              <InvoiceLineItemRow.Slot lineItem={line} />
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td>Total</td>
          <td></td>
          <td></td>
          <td></td>
          <td data-testid="invoice-amount">{formatMoney(total)}</td>
          <td></td>
        </tr>
      </tfoot>
    </table>
  );
}

import { Link } from '@tanstack/react-router';
import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useInvoices, useSendInvoice } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
// Each row shows its status, which is WORKED OUT from the payments recorded against the invoice
// (SENT while unpaid, PARTIAL once part paid, PAID once covered), and the control for its next step:
// Send while DRAFT, then Open to record payments — there is no mark-paid-by-hand flip anymore. The
// ordering comes from the shared `invoiceSort` URL key (set by a toolbar control), so the server
// returns the rows already in order.
export function InvoiceList({ projectId }: { projectId: number }) {
  const [sort] = useSearchParam('invoiceSort', asString);
  const { data: invoices } = useInvoices(projectId, sort || undefined);
  const send = useSendInvoice(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
    <InvoiceListToolbar.Slot projectId={projectId} />
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
          <th>Issued</th>
          <th>Due</th>
          <th>Left to pay</th>
          <th>Status</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-issued">{invoice.issuedDate}</td>
            <td data-testid="invoice-due">{invoice.dueDate}</td>
            <td>
              <InvoiceRow.Slot invoice={invoice} />
            </td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td>
              <Link
                to="/invoices/$invoiceId"
                params={{ invoiceId: String(invoice.id) }}
                data-testid={`invoice-open-${invoice.id}`}
              >
                Open
              </Link>
              {invoice.status === 'DRAFT' && (
                <button
                  type="button"
                  data-testid={`invoice-send-${invoice.id}`}
                  disabled={send.isPending}
                  onClick={() => send.mutate({ id: invoice.id })}
                >
                  Send
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
        </tr>
      </tfoot>
    </table>
    </>
  );
}

