2	
3	import java.math.BigDecimal;
4	import org.springframework.web.bind.annotation.RequestParam;
5	import net.officefloor.web.ObjectResponse;
6	
7	/**
8	 * {@code GET /api/invoices/summary?invoiceId=<id>} — the money breakdown for one invoice: its
9	 * subtotal (the worked-out sum of its line items, Flyway V13/V14, kept in the amount column), the
10	 * percentage discount taken off it (Flyway V27), the discount in money, and the final total
11	 * (subtotal minus discount). The figures are worked out on the server so the money math lives in one
12	 * place; an invoice with no discount simply bills its full subtotal. Wired by
13	 * {@code officefloor/rest/api/invoices/summary.GET.yml}.
14	 */
15	public class InvoiceSummaryGetLogic {
